// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, bytes memory data) public {
        vm.assume(amount > 0);
        Helper h = new Helper();

        vm.deal(address(c), amount);

        uint256 balanceBefore = address(c).balance;

        vm.prank(c.owner());
        c.sendMoney(address(h), amount, data);

        assertTrue(address(c).balance == balanceBefore - amount);
    }
}

contract Helper {
    fallback() external payable { }
}
